        "Eril ve nötr isimlerde ein, dişillerde eine kullanılır. Akkusativ'de eril isimler einen alır: Ich habe einen Bruder. Dativ'de: einem (eril/nötr), einer (dişil). Çoğulda belirsiz artikel yoktur; olumsuzlukta kein kullanılır.",
        "Ein aynı zamanda 'bir' sayısıdır: Ich habe nur ein Kind. O zaman vurgulu söylenir."
