        "Karşılaştırma dereceleri: groß, größer, am größten. İsmin önünde çekimlenir: ein großer Tisch, eine große Stadt, ein großes Zimmer.",
        "İnsanın boyu için groß „uzun boylu” demektir: Er ist 1,90 Meter groß."
