        "Kullanım: in den Laden gehen (dükkâna gitmek), im Laden einkaufen. Birleşik kelimelerde: Blumenladen (çiçekçi dükkânı), Bioladen, Schreibwarenladen. Büyük markete Supermarkt denir.",
        "Der Fensterladen (çoğulu die Fensterläden) pencere kepengidir. laden fiili (yüklemek, şarj etmek) aynı yazılır, ama bir fiildir: Ich lade mein Handy."
