        "Üstünlük derecesi: lauter (daha yüksek sesle), en üstünlük derecesi: am lautesten. İsmin önünde: ein lauter Knall, laute Musik. Zıt anlamlısı leise.",
        "Laut aynı zamanda „…e göre” anlamında bir edattır (laut Gesetz — kanuna göre), ama bu başka bir kelimedir; der Laut ismi ise „ses” demektir."
