        "fernsehen (televizyon izlemek) fiilinden türemiş bir isimdir. Cihaza der Fernseher, etkinliğe ise fernsehen denir.",
        "İsim büyük harfle yazılır; fiil olarak fernsehen ayrılabilen bir fiildir."
