        "Guten Appetit! yemekten önce söylenen bir dilektir, Türkçedeki \"Afiyet olsun!\" gibi. Belirli bir yiyeceğe istek duyulduğunda Appetit auf + belirtme hâli (Akkusativ) kullanılır: Appetit auf Eis.",
        "Der Appetit, der Hunger sözcüğüne yakındır; ancak iştah yemek yeme isteğidir, açlık ise fiziksel bir ihtiyaçtır."
